// @ts-nocheck
import {
	Component,
	Element,
	Event,
	type EventEmitter,
	Host,
	Prop,
	State,
	h,
} from "@stencil/core";

import { remove } from "../../../icons/index";
import getBootstrapConfig from "../../utils/getBootstrapConfig";

/**
 * @since 0.0.6
 * @status beta
 *
 */
@Component({
	tag: "hbr-grid-item",
	styleUrl: "hbr-grid-item.scss",
	shadow: false,
})
export class HbrGridItem {
	@Element() host: HTMLHbrGridItemElement;

	@State() state: { [key: string]: unknown } = null;

	@Event({ eventName: "hbr-select-grid-item" })
	selectGridItem: EventEmitter<string>;

	@Event({ eventName: "hbr-remove-grid-item" })
	removeGridItem: EventEmitter<string>;

	@Event({ eventName: "hbr-add-grid-item" }) addGridItem: EventEmitter<string>;

	/**
	 * Universally unique identifier for the layout-item. used to persist
	 * user preferences
	 */
	@Prop() uuid: string;

	/**
	 * Type of grid item, overrides grid level type
	 */
	@Prop() type: "custom" | "dashboard" | "cards";

	/**
	 * Width of layout item in CSS length units
	 **/
	@Prop() width: string;

	/**
	 * Height of layout item in CSS length units
	 */
	@Prop() height: string;

	/**
	 * Same as width property, but includes breakpoints to handle responsiveness
	 **/
	@Prop() responsiveWidth: { small: string; medium: string; large: string };

	/**
	 * Same as height property, but includes breakpoints to handle responsiveness
	 */
	@Prop() responsiveHeight: { small: string; medium: string; large: string };

	/**
	 * Whether it's allowed to select item or no
	 */
	@Prop() notSelectable = false;

	/**
	 * Sets property selection status
	 */
	@Prop() selected = false;

	/**
	 * Can grid item be removable or not
	 */
	@Prop() isRemovable = true;

	/**
	 * Calculated by grid component screen width size
	 */
	@Prop() screenSize: { width: string; height: string };

	/**
	 * sets cursor "grabbing" for moving atm items
	 */
	@Prop() isMoving = false;

	parent: HTMLHbrGridElement;

	selectLayoutItemHandler = () => {
		this.selectGridItem.emit(this.uuid);
	};

	removeItemHandler = () => {
		this.removeGridItem.emit(this.uuid);
	};

	componentWillLoad() {
		this.parent = this.host.closest("hbr-grid");
	}

	componentDidLoad() {
		this.runChecks();
		this.addGridItem.emit(this.uuid);
		window.addEventListener("hbr-grid-state-updated", this.updateStateHandler);
	}

	disconnectedCallback() {
		window.removeEventListener(
			"hbr-grid-state-updated",
			this.updateStateHandler,
		);
	}

	private runChecks() {
		if (!this.uuid) {
			console.warn("uuid is a required property for hbr-layout-item");
		}
	}

	private getWidth = () => {
		if (this.responsiveWidth) {
			return this.responsiveWidth[this.screenSize?.width];
		}
		return this.width;
	};

	private getHeight = () => {
		if (this.responsiveHeight) {
			return this.responsiveHeight[this.screenSize?.height];
		}
		return this.height;
	};

	updateStateHandler = (e) => {
		if (e.target === this.host.closest("hbr-grid")) {
			// @ts-ignore
			this.host.querySelector("div").state = e.detail;
		}
	};

	render() {
		if (!this.parent) return null;
		if (this.host.querySelector("div")) {
			// @ts-ignore
			this.host.querySelector("div").selected = this.selected;
			if (this.isRemovable && this.parent.removeItemsAllowed) {
				this.host.querySelector("div").removeGridItem = this.removeItemHandler;
			}
		}

		const type = this.type || this.parent.type;
		const customSystemIcons = getBootstrapConfig()?.systemIcons;
		return (
			<Host
				style={{
					width: this.getWidth(),
					height: this.getHeight(),
				}}
			>
				<div class="hbr-css--grid-item--content">
					<div
						class={`
              hbr-css--grid-item--framework-wrapper
              ${
								this.parent.muuriConfig.dragEnabled
									? "hbr-css--grid-item--drag-enabled"
									: ""
							}
              ${this.isMoving ? "hbr-css--grid-item--item-moving" : ""}
              hbr-css--grid-item--type-${type}
            `}
						onClick={this.selectLayoutItemHandler}
						onKeyUp={(event) => {
							if (event.key === "Enter") {
								this.selectLayoutItemHandler();
							}
						}}
					>
						{this.parent.type === "dashboard" &&
							this.isRemovable &&
							this.parent.removeItemsAllowed && (
								<div
									part="deleteIcon"
									class="removeGridItem"
									onClick={this.removeItemHandler}
									onKeyUp={(event) => {
										if (event.key === "Enter") {
											this.removeItemHandler();
										}
									}}
								>
									<hbr-icon asset={customSystemIcons?.remove || remove} />
								</div>
							)}
						<slot />
					</div>
				</div>
			</Host>
		);
	}
}
